"use client"

import animation from "react-useanimations/lib/batteryCharging"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Battery Charging" from https://useanimations.com (MIT): https://useanimations.com/icons/battery-charging
export function AnimatedBatteryCharging(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="hover-replay"
      {...props}
    />
  )
}
